 26	        public ConfirmationRequestedEventArgs(string title, string message, ConfirmationIcon icon = ConfirmationIcon.Warning, ConfirmationButton buttons = ConfirmationButton.YesNo)
 27	        {
 28	            Title = title;
 29	            Message = message;
 30	            Icon = icon;
 31	            Buttons = buttons;
 32	            Result = ConfirmationResult.None;
 33	        }
 34	    }
 35	
 36	    public partial class DiffDialogViewModel : ObservableObject, IDisposable
 37	    {
 38	        private readonly MainViewModel _mainViewModel;
 39	        private readonly ListCollectionView _filteredDiffLines;
 40	        private bool _suppressCollectionNotification;
 41	        private string _lastDiffSignature = string.Empty;
 42	        private bool _isRefreshing;
