 58	
 59	        public DiffDialogViewModel(IEnumerable<DiffLineModel> trimmedLines, IEnumerable<DiffLineModel> fullLines, MainViewModel mainViewModel)
 60	        {
 61	            _mainViewModel = mainViewModel;
 62	            var trimmedList = trimmedLines.ToList();
 63	            DiffLines = new ObservableCollection<DiffLineModel>(fullLines);
 64	            _filteredDiffLines = new ListCollectionView(DiffLines);
 65	            _filteredDiffLines.Filter = FilterDiffLines;
 66	            DiffLines.CollectionChanged += OnDiffCollectionChanged;
 67	            UpdateReferenceCommand = new AsyncRelayCommand(UpdateReferenceWithConfirmationAsync, CanUpdateReference);
 68	            FixLoadOrderCommand = _mainViewModel.FixLoadOrderCommand;
 69	            ReEnableModCommand = new AsyncRelayCommand<DiffLineModel>(ReEnableModAsync);
 70	            RemoveNewModCommand = new AsyncRelayCommand<DiffLineModel>(RemoveNewModAsync);
 71	            ReplaceRemovedModCommand = new AsyncRelayCommand<(DiffLineModel Removed, DiffLineModel Replacement)>(ReplaceRemovedModAsync);
 72	            ToggleDependentChangesCommand = new RelayCommand<DiffLineModel>(ToggleDependentChanges);
 73	            _mainViewModel.PropertyChanged += OnMainViewModelPropertyChanged;
 74	            
 75	            // Subscribe to configuration validation changes
 76	            var configCoordinator = _mainViewModel.GetConfigurationCoordinator();
 77	            IsConfigValid = configCoordinator.IsConfigValid;
 78	            configCoordinator.ValidationChanged += OnConfigValidationChanged;
 79	            
 80	            // Subscribe to file monitoring coordinator's change detected event
 81	            var coordinator = _mainViewModel.GetFileMonitoringCoordinator();
 82	            coordinator.ChangeDetected += OnFileChangeDetected;
 83	            
 84	            ApplyLineNumbers(DiffLines);
 85	            UpdateDiffState();
 86	            _lastDiffSignature = BuildSignature(trimmedList);
 87	            DiffStatusMessage = Texts.DifferencesLoadedStatus;
 88	        }
