 90	        /// <summary>
 91	        /// Test-only constructor. Accepts a pre-populated diff collection and skips all
 92	        /// coordinator subscriptions that require a full <see cref="MainViewModel"/> dependency
 93	        /// graph. Not for production use.
 94	        /// </summary>
 95	        [System.ComponentModel.EditorBrowsable(System.ComponentModel.EditorBrowsableState.Never)]
 96	        internal DiffDialogViewModel(ObservableCollection<DiffLineModel> diffLines)
