100	            _filteredDiffLines = new ListCollectionView(DiffLines);
101	            _filteredDiffLines.Filter = FilterDiffLines;
102	            DiffLines.CollectionChanged += OnDiffCollectionChanged;
103	            UpdateReferenceCommand = new AsyncRelayCommand(() => Task.CompletedTask);
104	            FixLoadOrderCommand = new AsyncRelayCommand(() => Task.CompletedTask);
105	            ReEnableModCommand = new AsyncRelayCommand<DiffLineModel>(_ => Task.CompletedTask);
106	            RemoveNewModCommand = new AsyncRelayCommand<DiffLineModel>(_ => Task.CompletedTask);
107	            ReplaceRemovedModCommand = new AsyncRelayCommand<(DiffLineModel Removed, DiffLineModel Replacement)>(_ => Task.CompletedTask);
108	            ToggleDependentChangesCommand = new RelayCommand<DiffLineModel>(ToggleDependentChanges);
109	            ApplyLineNumbers(DiffLines);
110	            UpdateDiffState();
111	        }
